svg.script:

(() => {
    const key = document.getElementById('key');
    const plunger = document.getElementById('plunger');

    const shadow = document.getElementById('key-shadow');
    const side = document.getElementById('key-side');
    const surface = document.getElementById('key-surface');
    const moon = document.getElementById('moon');

    let dark = false;
    let releaseTimer = null;

    function applyTheme() {
        if (dark) {
            shadow.setAttribute('fill', '#000000');

            side.setAttribute(
                'fill',
                'url(#side-dark)'
            );

            surface.setAttribute(
                'fill',
                'url(#surface-dark)'
            );

            surface.setAttribute(
                'stroke',
                '#404040'
            );

            moon.setAttribute(
                'fill',
                '#fafafa'
            );

            return;
        }

        shadow.setAttribute(
            'fill',
            '#737373'
        );

        side.setAttribute(
            'fill',
            'url(#side-light)'
        );

        surface.setAttribute(
            'fill',
            'url(#surface-light)'
        );

        surface.setAttribute(
            'stroke',
            '#bdbdbd'
        );

        moon.setAttribute(
            'fill',
            '#404040'
        );
    }

    function animatePress() {
        plunger.style.transform =
            'translateY(7px)';

        if (releaseTimer !== null) {
            clearTimeout(releaseTimer);
        }

        releaseTimer = setTimeout(() => {
            plunger.style.transform =
                'translateY(0)';

            releaseTimer = null;
        }, 65);
    }

    function activate() {
        dark = !dark;

        applyTheme();
        animatePress();
    }

    key.addEventListener(
        'click',
        activate
    );

    key.addEventListener(
        'keydown',
        event => {
            if (
                event.key !== 'Enter' &&
                event.key !== ' '
            ) {
                return;
            }

            event.preventDefault();
            activate();
        }
    );
})();
